"""Model-service internals. CUDA imports and checkpoint downloads stay lazy."""

from __future__ import annotations

import io
import math
from contextlib import closing
from pathlib import Path

from .contracts import (
    MAX_PAGES,
    MAX_PIXELS,
    MAX_REGIONS,
    MAX_TEXT_BYTES,
    MODEL_REVISION,
    SOURCE_MODEL,
    source_hash,
    validate_input,
    validate_result,
)

CHECKPOINT_FILES = (
    "detector.pth",
    "recognizer.pth",
    "relational.pth",
    "charset.txt",
    "model_config.json",
)


def load_pipeline():
    import platform

    if platform.system() != "Linux" or platform.machine() not in {"x86_64", "amd64"}:
        raise RuntimeError("Nemotron OCR requires Linux amd64 and NVIDIA CUDA")
    import torch

    if not torch.cuda.is_available():
        raise RuntimeError(
            "Nemotron OCR requires NVIDIA CUDA; CPU fallback is unsupported"
        )
    from huggingface_hub import snapshot_download
    from nemotron_ocr.inference.pipeline_v2 import NemotronOCRV2

    root = (
        Path(
            snapshot_download(
                repo_id=SOURCE_MODEL,
                revision=MODEL_REVISION,
                allow_patterns=[f"v2_multilingual/{name}" for name in CHECKPOINT_FILES],
                max_workers=2,
            )
        )
        / "v2_multilingual"
    )
    if not all((root / name).is_file() for name in CHECKPOINT_FILES):
        # Do not let the upstream loader silently resolve an incomplete folder at main.
        raise RuntimeError("Nemotron OCR checkpoint cache is incomplete")
    return NemotronOCRV2(model_dir=str(root), detector_max_batch_size=1)


def _image(data: bytes):
    from PIL import Image

    image = Image.open(io.BytesIO(data))
    try:
        if getattr(image, "n_frames", 1) != 1:
            raise ValueError("Multi-frame images are unsupported; use a PDF")
        if not 0 < image.width * image.height <= MAX_PIXELS:
            raise ValueError("OCR image exceeds 25 million pixels")
        image.load()
        return image.convert("RGB")
    finally:
        image.close()


def _number(value) -> float:
    if (
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(value)
    ):
        raise ValueError("OCR model returned a non-finite number")
    return float(value)


def normalize_regions(predictions) -> list[dict]:
    if not isinstance(predictions, list) or len(predictions) > MAX_REGIONS:
        raise ValueError("OCR model returned invalid or excessive regions")
    regions = []
    text_size = 0
    for prediction in predictions:
        if not isinstance(prediction, dict) or not isinstance(
            prediction.get("text"), str
        ):
            raise TypeError("OCR model returned an invalid text region")
        confidence = _number(prediction.get("confidence"))
        if not 0 <= confidence <= 1:
            raise ValueError("OCR model returned invalid confidence")
        left, top, right, bottom = [
            _number(prediction.get(key)) for key in ("left", "lower", "right", "upper")
        ]
        if left > right or top > bottom:
            raise ValueError("OCR model returned an inverted bounding box")
        text_size += len(prediction["text"].encode())
        if text_size > MAX_TEXT_BYTES:
            raise ValueError("OCR text exceeds its limit")
        regions.append(
            {
                "text": prediction["text"],
                "confidence": confidence,
                "bbox": [
                    max(0.0, min(1.0, value)) for value in (left, top, right, bottom)
                ],
            }
        )
    return regions


class NemotronOcrBackend:
    def __init__(self, *, pipeline_factory=load_pipeline):
        self._factory = pipeline_factory
        self._pipeline = None

    def prepare(self):
        if self._pipeline is None:
            self._pipeline = self._factory()
        return self

    def extract(
        self, data: bytes, *, suffix: str, merge_level: str = "paragraph"
    ) -> dict:
        suffix = validate_input(data, suffix, merge_level)
        pages = []

        def recognize(image):
            # Validate/decode a complete page before starting or downloading a model.
            self.prepare()
            import numpy as np

            regions = normalize_regions(
                self._pipeline(np.array(image), merge_level=merge_level)
            )
            page = {
                "page_number": len(pages) + 1,
                "width": image.width,
                "height": image.height,
                "text": "\n".join(region["text"] for region in regions),
                "regions": regions,
            }
            if (
                sum(len(item["regions"]) for item in pages) + len(regions) > MAX_REGIONS
                or sum(len(item["text"].encode()) for item in pages)
                + len(page["text"].encode())
                > MAX_TEXT_BYTES
            ):
                raise ValueError("OCR document exceeds region or text limits")
            pages.append(page)

        if suffix == ".pdf":
            import pypdfium2 as pdfium

            with pdfium.PdfDocument(data) as document:
                if not 0 < len(document) <= MAX_PAGES:
                    raise ValueError("OCR PDF must contain between 1 and 50 pages")
                for index in range(len(document)):
                    with closing(document[index]) as page:
                        width, height = page.get_size()
                        if not all(
                            math.isfinite(value) and value > 0
                            for value in (width, height)
                        ):
                            raise ValueError("Invalid PDF page dimensions")
                        # Bound raster allocation before invoking PDFium.
                        scale = min(2.0, math.sqrt(MAX_PIXELS / (width * height)))
                        while (
                            math.ceil(width * scale) * math.ceil(height * scale)
                            > MAX_PIXELS
                        ):
                            scale *= 0.99
                        with closing(page.render(scale=scale)) as bitmap:
                            image = bitmap.to_pil().convert("RGB")
                            try:
                                recognize(image)
                            finally:
                                image.close()
        else:
            with _image(data) as image:
                recognize(image)
        result = {
            "schema": "mn.nvidia_ocr.result.v1",
            "source_model": SOURCE_MODEL,
            "model_revision": MODEL_REVISION,
            "variant": "v2_multilingual",
            "input_sha256": source_hash(data),
            "merge_level": merge_level,
            "pages": pages,
            "warnings": [
                f"no_text_detected:page_{page['page_number']}"
                for page in pages
                if not page["text"].strip()
            ],
        }
        return validate_result(result)

"""Portable request/result contracts and a data-only managed model recipe."""

from __future__ import annotations

import base64
import copy
import hashlib
import json

SOURCE_MODEL = "nvidia/nemotron-ocr-v2"
MODEL_REVISION = "0e83e83f17943524b90afa6c0fd82ac2bc1a40ca"
MODEL_ID = "nvidia-nemotron-ocr-v2:0.1.0"
MODEL_IMAGE = "docker.io/homerquan/nvidia-ocr:0.1.0"
MAX_INPUT_BYTES = 32 * 1024 * 1024
MAX_RESULT_BYTES = 8 * 1024 * 1024
MAX_TEXT_BYTES = 4 * 1024 * 1024
MAX_PAGES = 50
MAX_PIXELS = 25_000_000
MAX_REGIONS = 10_000
MERGE_LEVELS = {"word", "sentence", "paragraph"}
SUFFIXES = {".pdf", ".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp", ".webp"}

REGION_SCHEMA = {
    "type": "object",
    "properties": {
        "text": {"type": "string", "maxLength": MAX_TEXT_BYTES},
        "confidence": {"type": "number", "minimum": 0, "maximum": 1},
        "bbox": {
            "type": "array",
            "minItems": 4,
            "maxItems": 4,
            "items": {"type": "number", "minimum": 0, "maximum": 1},
        },
    },
    "required": ["text", "confidence", "bbox"],
    "additionalProperties": False,
}
PAGE_SCHEMA = {
    "type": "object",
    "properties": {
        "page_number": {"type": "integer", "minimum": 1, "maximum": MAX_PAGES},
        "width": {"type": "integer", "minimum": 1, "maximum": MAX_PIXELS},
        "height": {"type": "integer", "minimum": 1, "maximum": MAX_PIXELS},
        "text": {"type": "string", "maxLength": MAX_TEXT_BYTES},
        "regions": {"type": "array", "maxItems": MAX_REGIONS, "items": REGION_SCHEMA},
    },
    "required": ["page_number", "width", "height", "text", "regions"],
    "additionalProperties": False,
}
RESULT_SCHEMA = {
    "type": "object",
    "properties": {
        "schema": {"const": "mn.nvidia_ocr.result.v1"},
        "source_model": {"const": SOURCE_MODEL},
        "model_revision": {"const": MODEL_REVISION},
        "variant": {"const": "v2_multilingual"},
        "input_sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"},
        "merge_level": {"enum": sorted(MERGE_LEVELS)},
        "pages": {
            "type": "array",
            "minItems": 1,
            "maxItems": MAX_PAGES,
            "items": PAGE_SCHEMA,
        },
        "warnings": {
            "type": "array",
            "maxItems": MAX_PAGES,
            "items": {"type": "string", "maxLength": 100},
        },
    },
    "required": [
        "schema",
        "source_model",
        "model_revision",
        "variant",
        "input_sha256",
        "merge_level",
        "pages",
        "warnings",
    ],
    "additionalProperties": False,
}


def runtime_model_spec(*, image: str = MODEL_IMAGE) -> dict:
    """Return a fresh SDK-owned Docker/HTTP JSON recipe, without side effects."""
    return {
        "id": MODEL_ID,
        "model": MODEL_ID,
        "name": "NVIDIA Nemotron OCR v2",
        "source": "docker",
        "provider": "docker_model_runner",
        "backend": "docker",
        "backends": ["docker"],
        "protocol": "http_json",
        "model_type": "ocr",
        "input_modalities": ["image"],
        "requirements": {"min_vram_gb": 48, "required_capabilities": ["cuda"]},
        "docker": {
            "image": image,
            "port": 30084,
            "container_port": 8000,
            "gpus": "all",
            "shm_size": "8g",
            "api_path": "/v1",
            "ready_path": "/health",
            "ready_timeout": 3600,
            "cache_path": "/cache",
            "environment": {
                "HF_HOME": "/cache",
                "HF_HUB_DISABLE_TELEMETRY": "1",
                "DO_NOT_TRACK": "1",
            },
        },
    }


def validate_input(data: bytes, suffix: str, merge_level: str) -> str:
    if not isinstance(data, bytes) or not 0 < len(data) <= MAX_INPUT_BYTES:
        raise ValueError("OCR input must be nonempty bytes within 32 MiB")
    if not isinstance(suffix, str) or suffix.lower() not in SUFFIXES:
        raise ValueError("Unsupported OCR document format")
    if not isinstance(merge_level, str) or merge_level not in MERGE_LEVELS:
        raise ValueError("merge_level must be word, sentence or paragraph")
    suffix = suffix.lower()
    signatures = {
        ".pdf": data.startswith(b"%PDF-"),
        ".png": data.startswith(b"\x89PNG\r\n\x1a\n"),
        ".jpg": data.startswith(b"\xff\xd8\xff"),
        ".jpeg": data.startswith(b"\xff\xd8\xff"),
        ".tif": data.startswith((b"II*\x00", b"MM\x00*")),
        ".tiff": data.startswith((b"II*\x00", b"MM\x00*")),
        ".bmp": data.startswith(b"BM"),
        ".webp": data.startswith(b"RIFF") and data[8:12] == b"WEBP",
    }
    if not signatures[suffix]:
        raise ValueError("OCR input signature does not match its document format")
    return suffix


def build_ocr_request(
    data: bytes, *, suffix: str, merge_level: str = "paragraph"
) -> dict:
    suffix = validate_input(data, suffix, merge_level)
    return {
        "path": "/ocr",
        "payload": {
            "document_base64": base64.b64encode(data).decode("ascii"),
            "suffix": suffix,
            "merge_level": merge_level,
        },
    }


def detect_document_suffix(data: bytes) -> str:
    """Detect supported document bytes after a caller's staging renamed the file."""
    for suffix in (".pdf", ".png", ".jpg", ".tif", ".bmp", ".webp"):
        try:
            return validate_input(data, suffix, "paragraph")
        except ValueError:
            continue
    raise ValueError("Unsupported or invalid OCR document")


def validate_result(result: dict, *, input_sha256: str | None = None) -> dict:
    """Reject malformed/incomplete responses; preserve complete model text."""
    from jsonschema import Draft202012Validator

    encoded = json.dumps(result, ensure_ascii=False, allow_nan=False).encode()
    if len(encoded) > MAX_RESULT_BYTES:
        raise ValueError("OCR result exceeds 8 MiB")
    Draft202012Validator(RESULT_SCHEMA).validate(result)
    if input_sha256 is not None and result["input_sha256"] != input_sha256:
        raise ValueError("OCR result does not match its source document")
    region_count, text_bytes = 0, 0
    for number, page in enumerate(result["pages"], 1):
        if page["page_number"] != number or page["width"] * page["height"] > MAX_PIXELS:
            raise ValueError("Invalid OCR page order or dimensions")
        if page["text"] != "\n".join(region["text"] for region in page["regions"]):
            raise ValueError("OCR page text does not match its regions")
        for region in page["regions"]:
            left, top, right, bottom = region["bbox"]
            if left > right or top > bottom:
                raise ValueError("Invalid OCR bounding box ordering")
        region_count += len(page["regions"])
        text_bytes += len(page["text"].encode())
    if region_count > MAX_REGIONS or text_bytes > MAX_TEXT_BYTES:
        raise ValueError("OCR result exceeds region or text limits")
    return copy.deepcopy(result)


def source_hash(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

"""Managed, bounded OCR HTTP service. No client paths or remote URLs are accepted."""

from __future__ import annotations

import asyncio
import base64
import binascii
import json
from contextlib import asynccontextmanager

from fastapi import FastAPI, HTTPException, Request

from .backend import NemotronOcrBackend
from .contracts import MAX_INPUT_BYTES

MAX_REQUEST_BYTES = 4 * ((MAX_INPUT_BYTES + 2) // 3) + 1024


def create_app(*, backend_factory=NemotronOcrBackend):
    gate = asyncio.Lock()

    @asynccontextmanager
    async def lifespan(app):
        # SDK first-use preparation starts this service. Readiness means weights loaded.
        app.state.backend = await asyncio.to_thread(lambda: backend_factory().prepare())
        try:
            yield
        finally:
            app.state.backend = None

    app = FastAPI(lifespan=lifespan, docs_url=None, redoc_url=None, openapi_url=None)

    @app.get("/health")
    def health():
        if getattr(app.state, "backend", None) is None:
            raise HTTPException(503, "OCR model is not ready")
        return {"ready": True}

    @app.post("/v1/ocr")
    async def ocr(request: Request):
        if gate.locked():
            raise HTTPException(429, "OCR model is busy")
        async with gate:
            body = bytearray()
            try:
                async with asyncio.timeout(30):
                    async for chunk in request.stream():
                        if len(body) + len(chunk) > MAX_REQUEST_BYTES:
                            raise HTTPException(
                                413, "OCR document exceeds request limit"
                            )
                        body.extend(chunk)
                payload = json.loads(body)
                if not isinstance(payload, dict) or set(payload) != {
                    "document_base64",
                    "suffix",
                    "merge_level",
                }:
                    raise ValueError("Invalid OCR request")
                encoded = payload["document_base64"]
                if not isinstance(encoded, str):
                    raise TypeError("Invalid OCR encoding")
                data = base64.b64decode(encoded, validate=True)
                return await asyncio.to_thread(
                    app.state.backend.extract,
                    data,
                    suffix=payload["suffix"],
                    merge_level=payload["merge_level"],
                )
            except HTTPException:
                raise
            except TimeoutError:
                raise HTTPException(408, "OCR request read timed out") from None
            except (ValueError, TypeError, KeyError, binascii.Error):
                raise HTTPException(
                    400, "Invalid or unsupported OCR document"
                ) from None
            except Exception:  # noqa: BLE001 - sanitize model and decoder diagnostics
                # Model exceptions may contain document text or filesystem paths.
                raise HTTPException(
                    503, "OCR inference failed; check model readiness"
                ) from None

    return app


def main():
    import uvicorn

    uvicorn.run(create_app(), host="0.0.0.0", port=8000, workers=1, access_log=False)


if __name__ == "__main__":
    main()
